// OTHVM — Social Media Hub (single Code node, parallel fan-out)
// Platforms: Telegram (live), X, Reddit, LinkedIn, Meta, TikTok (ready when env tokens exist).
// Operations: platforms | post | telegram | delete | history | help

const input = $json || {};
const op = String(input.operation || 'post').toLowerCase().trim();
const clean = (v) => String(v == null ? '' : v).trim();
const env = (k) => {
  try {
    return clean($env[k]);
  } catch (e) {
    return '';
  }
};
const http = (opts) => this.helpers.httpRequest(opts);
const clamp = (n, lo, hi) => Math.max(lo, Math.min(hi, Number(n) || lo));

const SB_URL = env('SUPABASE_URL').replace(/\/+$/, '');
const SB_KEY = env('SUPABASE_SERVICE_KEY');

async function request(opts) {
  try {
    return await http(opts);
  } catch (e) {
    let msg = (e && e.message) || 'request failed';
    const b = e && e.response && e.response.body;
    if (b) {
      if (typeof b === 'string') msg = b;
      else msg = b.description || b.error_description || b.error || b.message || JSON.stringify(b);
    }
    return { __error: String(msg).slice(0, 500) };
  }
}

const fail = (platform, status, error) => ({
  ok: false,
  platform,
  status: status || 'failed',
  error: String(error || '').slice(0, 500),
});

const cfg = {
  telegram: {
    label: 'Telegram',
    configured: !!env('TELEGRAM_BOT_TOKEN'),
    supported: true,
    env: ['TELEGRAM_BOT_TOKEN', 'OWNER_CHAT_ID'],
  },
  x: {
    label: 'X',
    configured: !!(env('X_USER_ACCESS_TOKEN') || env('X_ACCESS_TOKEN')),
    supported: true,
    env: ['X_USER_ACCESS_TOKEN'],
  },
  reddit: {
    label: 'Reddit',
    configured: !!(env('REDDIT_CLIENT_ID') && env('REDDIT_CLIENT_SECRET') && env('REDDIT_USERNAME') && env('REDDIT_PASSWORD')),
    supported: true,
    env: ['REDDIT_CLIENT_ID', 'REDDIT_CLIENT_SECRET', 'REDDIT_USERNAME', 'REDDIT_PASSWORD'],
  },
  linkedin: {
    label: 'LinkedIn',
    configured: !!(env('LINKEDIN_ACCESS_TOKEN') && env('LINKEDIN_AUTHOR_URN')),
    supported: true,
    env: ['LINKEDIN_ACCESS_TOKEN', 'LINKEDIN_AUTHOR_URN'],
  },
  meta: {
    label: 'Meta',
    configured: !!(env('META_PAGE_ID') && env('META_PAGE_ACCESS_TOKEN')),
    supported: true,
    env: ['META_PAGE_ID', 'META_PAGE_ACCESS_TOKEN'],
  },
  tiktok: {
    label: 'TikTok',
    configured: !!env('TIKTOK_ACCESS_TOKEN'),
    supported: false,
    env: ['TIKTOK_ACCESS_TOKEN', 'TIKTOK_OPEN_ID'],
    note: 'TikTok Content Posting API requires a chunked video/photo upload flow; not implemented in this hub.',
  },
};

const platformList = () =>
  Object.keys(cfg).map((id) => ({
    id,
    label: cfg[id].label,
    ready: cfg[id].configured && cfg[id].supported,
    configured: cfg[id].configured,
    supported: cfg[id].supported,
    env: cfg[id].env,
    note: cfg[id].note || null,
  }));

async function postTelegram(text, media, chatId) {
  const token = env('TELEGRAM_BOT_TOKEN');
  if (!token) return fail('telegram', 'not_configured', 'TELEGRAM_BOT_TOKEN is not configured.');
  const chat = clean(chatId) || env('OWNER_CHAT_ID');
  if (!chat) return fail('telegram', 'invalid', 'chat_id is required (or set OWNER_CHAT_ID).');
  if (!text && !media) return fail('telegram', 'invalid', 'message or media_url is required.');
  const isVideo = /\.(mp4|mov|m4v|webm)(\?|#|$)/i.test(media);
  const method = media ? (isVideo ? 'sendVideo' : 'sendPhoto') : 'sendMessage';
  const body = media
    ? { chat_id: chat, [isVideo ? 'video' : 'photo']: media, caption: text || '' }
    : { chat_id: chat, text: text || '' };
  const r = await request({
    method: 'POST',
    url: 'https://api.telegram.org/bot' + token + '/' + method,
    body,
    json: true,
    timeout: 30000,
  });
  if (!r || r.__error || r.ok !== true) {
    return fail('telegram', 'failed', (r && (r.__error || r.description)) || 'Telegram rejected the request.');
  }
  const m = r.result || {};
  const uname = m.chat && m.chat.username;
  return {
    ok: true,
    platform: 'telegram',
    status: 'posted',
    id: m.message_id,
    url: uname ? 'https://t.me/' + uname : null,
    chat_id: chat,
  };
}

async function deleteTelegram(chatId, messageId) {
  const token = env('TELEGRAM_BOT_TOKEN');
  if (!token) return fail('telegram', 'not_configured', 'TELEGRAM_BOT_TOKEN is not configured.');
  const chat = clean(chatId) || env('OWNER_CHAT_ID');
  const mid = Number(messageId);
  if (!chat || !mid) return fail('telegram', 'invalid', 'chat_id and numeric message_id are required.');
  const r = await request({
    method: 'POST',
    url: 'https://api.telegram.org/bot' + token + '/deleteMessage',
    body: { chat_id: chat, message_id: mid },
    json: true,
    timeout: 20000,
  });
  if (!r || r.__error || r.ok !== true) {
    return fail('telegram', 'failed', (r && (r.__error || r.description)) || 'Telegram rejected the delete.');
  }
  return { ok: true, platform: 'telegram', status: 'deleted', id: mid, chat_id: chat };
}

async function postX(text, media) {
  const token = env('X_USER_ACCESS_TOKEN') || env('X_ACCESS_TOKEN');
  if (!token) return fail('x', 'not_configured', 'X_USER_ACCESS_TOKEN is not configured (user-context OAuth 2.0 token required to post).');
  if (media) return fail('x', 'unsupported', 'X media upload is not implemented in this hub; post text only.');
  if (!text) return fail('x', 'invalid', 'message is required.');
  const r = await request({
    method: 'POST',
    url: 'https://api.x.com/2/tweets',
    headers: { Authorization: 'Bearer ' + token },
    body: { text },
    json: true,
    timeout: 20000,
  });
  if (!r || r.__error) return fail('x', 'failed', r && r.__error);
  const id = r && r.data && r.data.id;
  if (!id) return fail('x', 'failed', (r && (r.detail || r.title || JSON.stringify(r.errors || r))) || 'X API rejected the post.');
  return { ok: true, platform: 'x', status: 'posted', id, url: 'https://x.com/i/web/status/' + id };
}

async function postReddit(text, media, title, subreddit, linkUrl) {
  const cid = env('REDDIT_CLIENT_ID');
  const sec = env('REDDIT_CLIENT_SECRET');
  const user = env('REDDIT_USERNAME');
  const pass = env('REDDIT_PASSWORD');
  if (!cid || !sec || !user || !pass) {
    return fail('reddit', 'not_configured', 'REDDIT_CLIENT_ID, REDDIT_CLIENT_SECRET, REDDIT_USERNAME, and REDDIT_PASSWORD are required.');
  }
  const sr = clean(subreddit) || env('REDDIT_DEFAULT_SUBREDDIT');
  if (!sr) return fail('reddit', 'invalid', 'subreddit is required.');
  if (!text && !linkUrl) return fail('reddit', 'invalid', 'message or url is required.');
  const ua = env('REDDIT_USER_AGENT') || 'OTHVM/1.0';
  const auth = await request({
    method: 'POST',
    url: 'https://www.reddit.com/api/v1/access_token',
    headers: {
      Authorization: 'Basic ' + btoa(cid + ':' + sec),
      'Content-Type': 'application/x-www-form-urlencoded',
      'User-Agent': ua,
    },
    body:
      'grant_type=password&username=' +
      encodeURIComponent(user) +
      '&password=' +
      encodeURIComponent(pass),
    timeout: 20000,
  });
  if (!auth || auth.__error || !auth.access_token) {
    return fail('reddit', 'failed', (auth && (auth.__error || auth.error)) || 'Reddit authentication failed.');
  }
  const kind = linkUrl ? 'link' : 'self';
  const payload =
    'sr=' +
    encodeURIComponent(sr) +
    '&title=' +
    encodeURIComponent(clean(title) || text.slice(0, 100)) +
    '&kind=' +
    kind +
    '&api_type=json' +
    (linkUrl ? '&url=' + encodeURIComponent(linkUrl) : '&text=' + encodeURIComponent(text));
  const r = await request({
    method: 'POST',
    url: 'https://oauth.reddit.com/api/submit',
    headers: {
      Authorization: 'Bearer ' + auth.access_token,
      'Content-Type': 'application/x-www-form-urlencoded',
      'User-Agent': ua,
    },
    body: payload,
    timeout: 20000,
  });
  if (!r || r.__error) return fail('reddit', 'failed', r && r.__error);
  const errs = r.json && r.json.errors;
  if (errs && errs.length) return fail('reddit', 'failed', JSON.stringify(errs));
  const data = (r.json && r.json.data) || {};
  if (!data.id) return fail('reddit', 'failed', 'Reddit did not return a post id.');
  const url = data.url ? (String(data.url).startsWith('http') ? data.url : 'https://www.reddit.com' + data.url) : null;
  return { ok: true, platform: 'reddit', status: 'posted', id: data.id, url };
}

async function postLinkedIn(text, media) {
  const token = env('LINKEDIN_ACCESS_TOKEN');
  const author = env('LINKEDIN_AUTHOR_URN');
  if (!token || !author) return fail('linkedin', 'not_configured', 'LINKEDIN_ACCESS_TOKEN and LINKEDIN_AUTHOR_URN are required.');
  if (media) return fail('linkedin', 'unsupported', 'LinkedIn media upload is not implemented in this hub; post text only.');
  if (!text) return fail('linkedin', 'invalid', 'message is required.');
  const body = {
    author,
    lifecycleState: 'PUBLISHED',
    specificContent: {
      'com.linkedin.ugc.ShareContent': {
        shareCommentary: { text },
        shareMediaCategory: 'NONE',
      },
    },
    visibility: { 'com.linkedin.ugc.MemberNetworkVisibility': 'PUBLIC' },
  };
  const r = await request({
    method: 'POST',
    url: 'https://api.linkedin.com/v2/ugcPosts',
    headers: { Authorization: 'Bearer ' + token, 'X-Restli-Protocol-Version': '2.0.0' },
    body,
    json: true,
    timeout: 20000,
  });
  if (!r || r.__error) return fail('linkedin', 'failed', r && r.__error);
  const id = r.id || r['$id'] || (r.value && r.value.id);
  if (!id) return fail('linkedin', 'failed', 'LinkedIn did not return a post id.');
  return { ok: true, platform: 'linkedin', status: 'posted', id, url: 'https://www.linkedin.com/feed/update/' + id };
}

async function postMeta(text, media) {
  const page = env('META_PAGE_ID');
  const token = env('META_PAGE_ACCESS_TOKEN');
  const ver = env('META_API_VERSION') || 'v23.0';
  if (!page || !token) return fail('meta', 'not_configured', 'META_PAGE_ID and META_PAGE_ACCESS_TOKEN are required.');
  if (!text && !media) return fail('meta', 'invalid', 'message or media_url is required.');
  const base = 'https://graph.facebook.com/' + ver + '/' + page;
  const r = media
    ? await request({
        method: 'POST',
        url: base + '/photos',
        body: { url: media, caption: text || '', access_token: token },
        json: true,
        timeout: 30000,
      })
    : await request({
        method: 'POST',
        url: base + '/feed',
        body: { message: text, access_token: token },
        json: true,
        timeout: 20000,
      });
  if (!r || r.__error) return fail('meta', 'failed', r && r.__error);
  const id = r.id || r.post_id;
  if (!id) return fail('meta', 'failed', (r.error && r.error.message) || 'Meta did not return a post id.');
  return { ok: true, platform: 'meta', status: 'posted', id, url: 'https://www.facebook.com/' + id };
}

async function postTikTok(text, media) {
  if (!env('TIKTOK_ACCESS_TOKEN')) return fail('tiktok', 'not_configured', 'TIKTOK_ACCESS_TOKEN is not configured.');
  return fail('tiktok', 'unsupported', 'TikTok requires a chunked video/photo upload flow; this hub does not implement it yet.');
}

async function publishOne(platform, text, media, extra) {
  try {
    if (platform === 'telegram') return await postTelegram(text, media, extra.chat_id);
    if (platform === 'x') return await postX(text, media);
    if (platform === 'reddit') return await postReddit(text, media, extra.title, extra.subreddit, extra.url);
    if (platform === 'linkedin') return await postLinkedIn(text, media);
    if (platform === 'meta') return await postMeta(text, media);
    if (platform === 'tiktok') return await postTikTok(text, media);
    return fail(platform, 'invalid', 'Unsupported platform.');
  } catch (e) {
    return fail(platform, 'failed', (e && e.message) || e);
  }
}

async function logResults(results, text, media) {
  if (!SB_URL || !SB_KEY) return { logged: 0, error: 'Supabase is not configured.' };
  const rows = results.map((r) => ({
    platform: r.platform,
    content: text || '',
    media_url: media || null,
    external_id: r.id != null ? String(r.id) : null,
    url: r.url || null,
    status: r.status || (r.ok ? 'posted' : 'failed'),
    error: r.error || null,
    metadata: { operation: op, chat_id: r.chat_id || null, dry_run: !!input.dry_run },
  }));
  const r = await request({
    method: 'POST',
    url: SB_URL + '/rest/v1/social_posts',
    headers: {
      apikey: SB_KEY,
      Authorization: 'Bearer ' + SB_KEY,
      'Content-Type': 'application/json',
      Prefer: 'return=minimal',
    },
    body: rows,
    json: true,
    timeout: 15000,
  });
  if (r && r.__error) return { logged: 0, error: r.__error };
  return { logged: rows.length };
}

async function history(limit) {
  if (!SB_URL || !SB_KEY) return { ok: false, error: 'Supabase is not configured.' };
  const n = clamp(limit, 1, 50);
  const r = await request({
    method: 'GET',
    url:
      SB_URL +
      '/rest/v1/social_posts?select=platform,status,content,external_id,url,error,created_at&order=created_at.desc&limit=' +
      n,
    headers: { apikey: SB_KEY, Authorization: 'Bearer ' + SB_KEY, Accept: 'application/json' },
    json: true,
    timeout: 15000,
  });
  if (r && r.__error) return { ok: false, error: r.__error };
  return { ok: true, count: (r || []).length, posts: r || [] };
}

// ---------- Operations ----------
if (op === 'platforms' || op === 'status' || op === 'help') {
  const platforms = platformList();
  return [
    {
      json: {
        ok: true,
        operation: 'platforms',
        platforms,
        ready: platforms.filter((p) => p.ready).map((p) => p.id),
        operations: ['platforms', 'post', 'telegram', 'delete', 'history', 'help'],
        fields: ['operation', 'platform', 'message', 'media_url', 'chat_id', 'message_id', 'title', 'subreddit', 'url', 'dry_run', 'limit'],
      },
    },
  ];
}

if (op === 'history') {
  const h = await history(input.limit);
  return [{ json: Object.assign({ operation: 'history' }, h) }];
}

if (op === 'delete') {
  const r = await deleteTelegram(input.chat_id, input.message_id);
  const log = await logResults([r], '', '');
  return [
    {
      json: {
        ok: r.ok,
        operation: 'delete',
        result: r,
        log,
        reply: (r.ok ? '✅ ' : '❌ ') + 'Telegram: ' + (r.ok ? 'تم حذف الرسالة ' + r.id : r.error),
      },
    },
  ];
}

if (op === 'post' || op === 'publish' || op === 'telegram') {
  const text = clean(input.message);
  const media = clean(input.media_url);
  if (!text && !media) {
    return [{ json: { ok: false, operation: 'post', error: 'message or media_url is required.' } }];
  }
  let requested = clean(input.platform).toLowerCase();
  if (op === 'telegram') requested = 'telegram';
  if (!requested) requested = 'telegram';
  let targets = requested
    .split(',')
    .map((s) => s.trim())
    .filter(Boolean);
  if (targets.indexOf('all') !== -1) {
    targets = Object.keys(cfg).filter((k) => cfg[k].supported && cfg[k].configured);
  }
  if (!targets.length) {
    return [{ json: { ok: false, operation: 'post', error: 'No configured platform for "all". Configure credentials first or name a platform.' } }];
  }
  const unknown = targets.filter((t) => !cfg[t]);
  if (unknown.length) {
    return [{ json: { ok: false, operation: 'post', error: 'Unknown platform(s): ' + unknown.join(', '), supported: Object.keys(cfg) } }];
  }

  if (input.dry_run) {
    return [
      {
        json: {
          ok: true,
          operation: 'post',
          dry_run: true,
          requested: targets,
          planned: targets.map((p) => ({
            platform: p,
            ready: cfg[p].configured && cfg[p].supported,
            note: cfg[p].note || (cfg[p].configured ? 'ready' : 'missing ' + cfg[p].env.join(', ')),
          })),
        },
      },
    ];
  }

  const extra = {
    chat_id: clean(input.chat_id),
    title: clean(input.title),
    subreddit: clean(input.subreddit),
    url: clean(input.url),
  };
  const results = await Promise.all(targets.map((p) => publishOne(p, text, media, extra)));
  const log = await logResults(results, text, media);
  const posted = results.filter((r) => r.ok).length;
  const reply = results
    .map((r) => (r.ok ? '✅ ' : '❌ ') + cfg[r.platform].label + (r.ok ? ' — تم النشر' : ' — ' + (r.error || r.status)))
    .join('\n');
  return [
    {
      json: {
        ok: posted > 0,
        operation: 'post',
        requested: targets,
        posted,
        failed: results.length - posted,
        results,
        log,
        reply,
      },
    },
  ];
}

return [
  {
    json: {
      ok: false,
      error: 'Unknown operation: ' + op,
      operations: ['platforms', 'post', 'telegram', 'delete', 'history', 'help'],
    },
  },
];
